{"dependencies":[],"lesson":"channel is main changes() (last direct row-change count, trigger-exempt); conflict is upsert DO UPDATE; savepoints need real snapshot semantics: rollback_to restores pending state as of savepoint creation, release of the outermost savepoint commits unless a BEGIN transaction is open.","scope":"disposable SQLite source; enumerate 3x3x2 family with native savepoint simulation, filter by receipts, answer only when all survivors agree","source":"def norm(a):
    c = a.get("connection", "main")
    if c != "other":
        c = "main"
    return c


def route(a, txn):
    if txn.get("main"):
        return "main"
    if txn.get("other"):
        return "other"
    return norm(a)


def view_of(pend, comm):
    v = dict(comm)
    for k in pend:
        if pend[k] is None:
            v.pop(k, None)
        else:
            v[k] = pend[k]
    return v


def write_entry(pend, comm, in_txn, key, value, op, conflict):
    if in_txn:
        exists = key in view_of(pend, comm)
        ch = 0
        if op == "put":
            if exists:
                if conflict == "ignore":
                    ch = 0
                elif conflict == "replace":
                    pend[key] = value
                    ch = 2
                else:
                    pend[key] = value
                    ch = 1
            else:
                pend[key] = value
                ch = 1
        elif op == "update":
            if exists:
                pend[key] = value
                ch = 1
        elif op == "delete":
            if exists:
                pend[key] = None
                ch = 1
        return ch
    exists = key in comm
    ch = 0
    if op == "put":
        if exists:
            if conflict == "ignore":
                ch = 0
            elif conflict == "replace":
                comm[key] = value
                ch = 2
            else:
                comm[key] = value
                ch = 1
        else:
            comm[key] = value
            ch = 1
    elif op == "update":
        if exists:
            comm[key] = value
            ch = 1
    elif op == "delete":
        if exists:
            comm.pop(key)
            ch = 1
    return ch


def flush(pend, comm):
    for k in pend:
        if pend[k] is None:
            comm.pop(k, None)
        else:
            comm[k] = pend[k]


def clear_conn(txn, began, pend, saves, c):
    txn[c] = False
    began[c] = False
    pend[c] = {}
    saves[c] = []


def find_idx(saves, name):
    idx = -1
    for i in range(len(saves)):
        if saves[i][0] == name:
            idx = i
    return idx


def simulate(cand, actions):
    comm = {}
    txn = {"main": False, "other": False}
    began = {"main": False, "other": False}
    pend = {"main": {}, "other": {}}
    saves = {"main": [], "other": []}
    total = {"main": 0, "other": 0}
    main_last = 0
    for a in actions:
        op = a.get("op")
        if op == "begin":
            c = norm(a)
            if not txn[c]:
                txn[c] = True
                began[c] = True
                pend[c] = {}
                saves[c] = []
        elif op == "commit":
            c = norm(a)
            if txn[c]:
                flush(pend[c], comm)
                clear_conn(txn, began, pend, saves, c)
        elif op == "rollback":
            c = norm(a)
            if txn[c]:
                clear_conn(txn, began, pend, saves, c)
        elif op == "savepoint":
            c = route(a, txn)
            if not txn[c]:
                txn[c] = True
                began[c] = False
                pend[c] = {}
                saves[c] = []
            saves[c].append([a.get("name"), dict(pend[c])])
        elif op == "rollback_to":
            c = route(a, txn)
            idx = find_idx(saves[c], a.get("name"))
            if idx >= 0:
                pend[c] = dict(saves[c][idx][1])
                saves[c] = saves[c][:idx + 1]
        elif op == "release":
            c = route(a, txn)
            idx = find_idx(saves[c], a.get("name"))
            if idx >= 0:
                saves[c] = saves[c][:idx]
                if len(saves[c]) == 0 and not began[c] and txn[c]:
                    flush(pend[c], comm)
                    clear_conn(txn, began, pend, saves, c)
        else:
            c = route(a, txn)
            ch = write_entry(pend[c], comm, txn[c], a.get("key"), a.get("value"), op, cand["conflict"])
            total[c] = total[c] + ch
            if c == "main":
                main_last = ch
    if cand["channel"] == "changes":
        chan = main_last
    elif cand["channel"] == "total_main":
        chan = total["main"]
    else:
        chan = total["main"] + total["other"]
    s = 0
    for v in comm.values():
        s = s + v
    return {"channel": chan, "count": len(comm), "sum": s}


def survivors(hist, source_id):
    out = []
    for conflict in ["ignore", "replace", "upsert"]:
        for channel in ["changes", "total_main", "both"]:
            for trig in [False, True]:
                cand = {"conflict": conflict, "channel": channel, "trigger": trig}
                ok = True
                for r in hist:
                    if r.get("source_id") != source_id:
                        continue
                    obs = r.get("observed")
                    res = simulate(cand, r.get("actions", []))
                    if res["channel"] != obs.get("channel"):
                        ok = False
                    if res["count"] != obs.get("committed_count"):
                        ok = False
                    if res["sum"] != obs.get("committed_sum"):
                        ok = False
                if ok:
                    out.append(cand)
    return out


def investigate(context, acquire):
    hist = acquire("history")
    cands = survivors(hist, context.get("source_id"))
    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = []
    for cand in cands:
        res = simulate(cand, actions)
        if goal == "channel":
            vals.append(res["channel"])
        elif goal == "committed_count":
            vals.append(res["count"])
        else:
            vals.append(res["sum"])
    if len(vals) == 0:
        return {"value": None, "unresolved": True}
    first = vals[0]
    for v in vals:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}
